fn take(arr: Vec<f32>, indices: Vec<usize>) -> Vec<f32> {
    let mut result = Vec::with_capacity(indices.len());
    for idx in indices {
        // We assume idx is within bounds of `arr`
        result.push(arr[idx]);
    }
    result
}

